 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bars = set()
    # Horizontal stripes are long, dense nonzero runs. Fill only gaps inside
    # the observed span; zero background beyond that span stays untouched.
    for r, row in enumerate(g):
        nz = [c for c, value in enumerate(row) if value != 0]
        if len(nz) >= 5 and nz[-1] - nz[0] >= 5:
            bars.add(r)
            for c in range(nz[0], nz[-1] + 1):
                if g[r][c] == 0:
                    left = next((g[r][j] for j in range(c - 1, nz[0] - 1, -1) if g[r][j]), 0)
                    right = next((g[r][j] for j in range(c + 1, nz[-1] + 1) if g[r][j]), 0)
                    if left and right and left == right:
                        g[r][c] = left
                    elif left and not right:
                        g[r][c] = left
                    elif right and not left:
                        g[r][c] = right
                    elif left and right:
                        g[r][c] = left if c - (c - 1) <= (c + 1) - c else right
    # Every nonzero cell at the bottom launches an upward ray. Its color
    # changes to the stripe color whenever that ray crosses a stripe.
    for c in range(w):
        if g[h - 1][c] == 0:
            continue
        color = g[h - 1][c]
        for r in range(h - 2, -1, -1):
            if r in bars and g[r][c] != 0:
                color = g[r][c]
            elif g[r][c] == 0:
                g[r][c] = color
    return g
